(function(){'use strict';
const copy=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validate(raw){const s=copy(raw);if(!['build','insert','extract','change','delete','sort','multiway','topk','frontier','binomial','fibonacci'].includes(s.operation))throw Error('Choose a supported heap operation.');if(s.operation==='fibonacci')return s;if(!Array.isArray(s.keys)||s.keys.length<1||s.keys.length>32||s.keys.some(x=>!Number.isInteger(x)||Math.abs(x)>999))throw Error('Use one through 32 integer keys between -999 and 999.');s.orientation=s.orientation||'min';if(!['min','max'].includes(s.orientation))throw Error('Choose min or max orientation.');s.arity=s.arity||2;if(!Number.isInteger(s.arity)||s.arity<2||s.arity>4)throw Error('Arity must be two, three or four.');if(['insert','change'].includes(s.operation)&&(!Number.isInteger(s.value)||Math.abs(s.value)>999))throw Error('New key must be an integer between -999 and 999.');if(['delete','change'].includes(s.operation)&&(!Number.isInteger(s.index)||s.index<0||s.index>=s.keys.length))throw Error('Target index must be an existing zero-based position.');if(s.operation==='topk'||s.operation==='frontier'){if(!Number.isInteger(s.k)||s.k<1||s.k>s.keys.length)throw Error('Rank/retained count must be between one and input size.');}return s;}
function evaluate(raw){const s=validate(raw),states=[];let a=s.keys?.map((key,id)=>({key,id:'E'+id}))||[],active=a.length,comparisons=0,swaps=0,moves=0,selected=[],aux=[],opIndex=null;
if(s.operation==='sort')s.orientation='max';if(s.operation==='topk')s.orientation='min';
const better=(x,y)=>s.orientation==='max'?x.key>y.key:x.key<y.key,parent=i=>Math.floor((i-1)/s.arity),children=i=>Array.from({length:s.arity},(_,j)=>s.arity*i+j+1).filter(j=>j<active),valid=()=>a.slice(0,active).every((x,i)=>i===0||!better(x,a[parent(i)]));
function snap(action,why,focus=[],complete=false,extra={}){states.push({kind:'array',array:copy(a),active,focus,complete,valid:valid(),index:opIndex,comparisons,swaps,moves,selected:copy(selected),aux:copy(aux),action,why,...extra});}
function cmp(i,j,why){comparisons++;snap('Compare '+a[i].key+' with '+a[j].key+'.',why,[a[i].id,a[j].id]);return better(a[i],a[j]);}
function swap(i,j,why){const x=a[i];a[i]=a[j];a[j]=x;swaps++;snap('Exchange positions '+i+' and '+j+'.',why,[a[i].id,a[j].id]);}
function up(i){opIndex=i;while(i>0){const p=parent(i);if(!cmp(i,p,'The only potential upward violation follows the active record.'))break;swap(i,p,'Move the better record upward and the displaced ancestor downward.');i=p;opIndex=i;}opIndex=null;}
function down(i){opIndex=i;while(children(i).length){const cs=children(i);let c=cs[0];for(const j of cs.slice(1))if(cmp(j,c,'Choose the best existing child; equal children keep the leftmost candidate.'))c=j;if(!cmp(c,i,'Stop if the best child does not precede its parent.'))break;swap(c,i,'Promote the best child; only the displaced record may still need repair.');i=c;opIndex=i;}opIndex=null;}
function build(){for(let i=Math.floor((active-2)/s.arity);i>=0;i--){snap('Repair subtree rooted at position '+i+'.','Its children have already been repaired by decreasing-index construction.',[a[i].id]);down(i);snap('Finish subtree '+i+'.','Only this completed subtree is certified; ancestors may still need repair.',[],false,{subtreeComplete:i});}snap('Complete heap construction.','Every active edge now satisfies the declared comparator.',[],true);}
function forest(){let roots=[],links=0,nextId=0;const cmp=(x,y)=>s.orientation==='max'?x.key>y.key:x.key<y.key;
const take=(action,why,canonical)=>states.push({kind:'forest',roots:copy(roots),links,complete:canonical,action,why,orientation:s.orientation});
const rank=x=>x.children.length;function carry(t){let r=rank(t);while(roots.some(x=>rank(x)===r)){const j=roots.findIndex(x=>rank(x)===r),other=roots.splice(j,1)[0];roots.push(t);take('Two trees collide at rank '+r+'.','Equal-rank linking carries their combined nodes to the next rank.',false);roots.pop();if(cmp(other,t)){const x=t;t=other;t.children.push(x);}else t.children.push(other);links++;r++;roots.push(t);take('Link two rank-'+(r-1)+' trees.','The better root stays above the entire losing tree; no record is discarded.',false);roots.pop();}roots.push(t);roots.sort((x,y)=>rank(x)-rank(y));}
take('Begin an empty binomial forest.','A canonical forest has at most one tree per rank.',true);for(const key of s.keys){carry({key,id:'B'+nextId++,children:[]});take('Complete singleton insertion of '+key+'.','Root ranks encode the new size in binary.',true);}return{spec:s,states,result:{roots:copy(roots),links,size:s.keys.length}};}
if(s.operation==='binomial')return forest();
if(s.operation==='fibonacci'){let roots=[{id:'F1',key:1,marked:false,children:[{id:'F4',key:4,marked:false,children:[{id:'F7',key:7,marked:false,children:[]},{id:'F9',key:9,marked:false,children:[]}]}]}];const all=()=>{const v=[];function walk(t){v.push(t);t.children.forEach(walk);}roots.forEach(walk);return v;};const take=(action,why,complete=true)=>{const nodes=all(),marks=nodes.filter(n=>n.marked).length;states.push({kind:'forest',roots:copy(roots),complete,action,why,rootCount:roots.length,marks,potential:roots.length+2*marks});};
take('Load the stated local Fibonacci forest.','This is an explicit local configuration, not a claim that the full insertion history is displayed.');let p=roots[0].children[0],n=p.children[0];n.key=0;take('Decrease node F7 from 7 to 0.','The parent edge fails until the cut is committed.',false);p.children.shift();roots.push(n);p.marked=true;take('Cut F7 and mark its nonroot parent F4.','First child loss leaves F4 attached; roots stay unmarked.');n=p.children[0];n.key=2;take('Decrease node F9 from 9 to 2.','The already-marked parent is about to lose its second child.',false);p.children.shift();roots.push(n);take('Cut F9 to the root list.','F4 has lost its second child; this is a temporary cascade checkpoint.',false);roots[0].children=[];p.marked=false;roots.push(p);take('Cut and unmark F4.','The cascade stops at root F1, which is not marked for child loss.');return{spec:s,states,result:{roots:copy(roots),potential:4}};}
snap('Read the exact input array.','Tree nodes correspond only to the active prefix.',[],false);
if(s.operation==='sort'){s.orientation='max';build();for(let m=active-1;m>0;m--){swap(0,m,'Move the current maximum into its final suffix position.');active=m;snap('Shrink the active heap to '+m+'.','The suffix is sorted and excluded from tree child accesses.');down(0);snap('Finish this sortdown repair.','The prefix is a max heap; the suffix remains final and sorted.',[],true);}snap('Complete ascending heapsort.','Every record remains present and the entire array is sorted.',[],true);}
else if(s.operation==='topk'){const input=a;a=[];active=0;s.orientation='min';for(let j=0;j<input.length;j++){const x=input[j];if(active<s.k){a.push(x);active++;snap('Retain stream record '+x.key+'.','The initial retained set is filling; repair the appended record.',[x.id],false,{streamIndex:j});up(active-1);}else if(x.key>a[0].key){selected.push(copy(a[0]));a[0]=x;moves++;snap('Replace weakest retained key with '+x.key+'.','The incoming candidate beats the retained minimum; repair only downward.',[x.id],false,{streamIndex:j});down(0);}else{snap('Reject candidate '+x.key+'.','It cannot improve the current largest retained keys.',[],true,{streamIndex:j});continue;}snap('Certify retained candidates.','The min-root exposes the weakest member of the top-k set.',[],true,{streamIndex:j});}}
else if(s.operation==='frontier'){if(!valid())throw Error('Frontier selection requires an already ordered source heap.');aux=[{...a[0],index:0}];snap('Initialize the source-root frontier.','Every unreturned entry has an ancestor at the frontier.',[],true);for(let j=0;j<s.k;j++){aux.sort((x,y)=>better(x,y)?-1:better(y,x)?1:x.index-y.index);const x=aux.shift();selected.push(x);snap('Select source position '+x.index+' with key '+x.key+'.','This candidate is extreme among every remaining source subtree.',[x.id],true);for(const k of children(x.index))aux.push({...a[k],index:k});snap('Expand its existing children.','The source stays unchanged; candidate positions delimit unexplored subtrees.',[x.id],true);}}
else if(s.operation==='build'||s.operation==='multiway')build();
else{if(!valid())throw Error('This operation requires the stated initial array to be a valid heap.');snap('Certify the stated initial heap.','All initial comparator edges and identities are valid.',[],true);if(s.operation==='insert'){const x={key:s.value,id:'NEW'};a.push(x);active++;moves++;snap('Append '+s.value+' at the next complete position.','Shape remains complete; only its upward relation may fail.',[x.id]);up(active-1);}
else if(s.operation==='extract'){selected.push(copy(a[0]));if(active===1){a.pop();active=0;}else{const x=a.pop();a[0]=x;active--;moves++;snap('Move the final record to the root.','Save the removed root and shrink before any child access.',[x.id]);down(0);}}
else if(s.operation==='change'){const i=s.index,old=a[i].key;a[i].key=s.value;snap('Change key at position '+i+' from '+old+' to '+s.value+'.','Record identity is retained while its comparison key changes.',[a[i].id]);if(i>0&&better(a[i],a[parent(i)]))up(i);else down(i);}
else if(s.operation==='delete'){const i=s.index;selected.push(copy(a[i]));if(i===active-1){a.pop();active--;}else{const x=a.pop();a[i]=x;active--;moves++;snap('Fill deleted position '+i+' with the final record.','Use the new parent relation to select upward versus downward repair.',[x.id]);if(i>0&&better(a[i],a[parent(i)]))up(i);else down(i);}}
snap('Complete '+s.operation+'.','Every remaining active edge is ordered and the live identity map is consistent.',[],true);}
const positions=Object.fromEntries(a.slice(0,active).map((x,i)=>[x.id,i]));return{spec:s,states,result:{array:a.map(x=>x.key),entries:copy(a),active,comparisons,swaps,moves,selected:copy(selected),positions,valid:valid(),rankValue:s.operation==='frontier'?selected.at(-1).key:undefined}};
}
function svg(spec,z){const W=760,H=400,txt=(x,y,v,cls='hp-prose',anchor='start')=>'<text x="'+x+'" y="'+y+'" text-anchor="'+anchor+'" class="'+cls+'">'+esc(v)+'</text>';let body='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 400" role="img" aria-label="Exact '+esc(spec.operation)+' checkpoint"><defs><marker id="hp-arrow" viewBox="0 0 8 8" refX="8" refY="4" markerWidth="4" markerHeight="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#527585"/></marker></defs><rect x="6" y="6" width="748" height="388" rx="12" fill="#f5f9fa"/>',nodes=[],edges=[],pos={},radius=27;
if(z.kind==='array'){const n=z.array.length,cw=Math.min(54,704/Math.max(1,n)),left=(W-cw*n)/2;for(let i=0;i<n;i++){const x=left+i*cw,entry=z.array[i];body+='<rect x="'+x+'" y="22" width="'+(cw-3)+'" height="42" rx="6" fill="'+(i<z.active?'#e8f2f3':'#efe4d3')+'" stroke="#9ab9c0"/>'+txt(x+(cw-3)/2,84,i,'hp-meta','middle')+'<g data-entity="array-'+entry.id+'">'+txt(x+(cw-3)/2,49,entry.key,'hp-key'+(String(entry.key).length>3?' hp-long':''),'middle')+'</g>';}
function leaves(i){const cs=Array.from({length:spec.arity},(_,j)=>spec.arity*i+j+1).filter(j=>j<z.active);return cs.length?cs.reduce((n,c)=>n+leaves(c),0):1;}
function layout(i,depth,lo,hi){if(i>=z.active)return;const e=z.array[i],cs=Array.from({length:spec.arity},(_,j)=>spec.arity*i+j+1).filter(j=>j<z.active);pos[e.id]={x:(lo+hi)/2,y:125+depth*61};nodes.push({...e,marked:false,label:e.id});let cursor=lo;const total=cs.reduce((n,c)=>n+leaves(c),0);for(const c of cs){const right=cursor+(hi-lo)*leaves(c)/total;edges.push([e.id,z.array[c].id]);layout(c,depth+1,cursor,right);cursor=right;}}
layout(0,0,32,568);if(!z.active)body+=txt(300,150,'Empty active heap','hp-prose','middle');body+='<path d="M592 108 V350" stroke="#cbdce1"/>'+txt(612,132,z.complete?'Completed':'Temporary');const lines=['Active: '+z.active,'Compares: '+z.comparisons,'Exchanges: '+z.swaps,'Moves: '+z.moves,'Order: '+String(z.valid)];lines.forEach((v,i)=>body+=txt(612,165+i*27,v));
if(z.aux.length){const v=z.aux.slice().sort((a,b)=>a.key-b.key).map(x=>x.key+'@'+x.index).join('  ');body+=txt(32,363,'Frontier: '+v,'hp-meta');}else if(z.selected.length)body+=txt(32,363,'Selected / removed: '+z.selected.map(x=>x.key).join(', '),'hp-meta');else body+=txt(32,363,(spec.orientation||'min')+' order; array IDs move with records.');
}else{const roots=z.roots;function leaves(t){return t.children.length?t.children.reduce((n,c)=>n+leaves(c),0):1;}let depthMax=0;function depth(t,d){depthMax=Math.max(depthMax,d);t.children.forEach(c=>depth(c,d+1));}roots.forEach(t=>depth(t,0));const gap=Math.min(64,235/Math.max(1,depthMax)),total=roots.reduce((n,r)=>n+leaves(r),0);let cursor=32;function layout(t,d,lo,hi){pos[t.id]={x:(lo+hi)/2,y:85+d*gap};nodes.push({...t,label:t.id+'/'+t.children.length});let x=lo,tot=t.children.reduce((n,c)=>n+leaves(c),0);for(const c of t.children){const y=x+(hi-lo)*leaves(c)/tot;edges.push([t.id,c.id]);layout(c,d+1,x,y);x=y;}}for(const r of roots){const hi=cursor+690*leaves(r)/Math.max(1,total);layout(r,0,cursor,hi);cursor=hi;}body+=txt(32,35,spec.operation==='fibonacci'?'Actual forest edges; orange ring = marked nonroot.':'Binomial rank = root degree; collisions are temporary.');body+=txt(32,375,spec.operation==='fibonacci'?'Roots '+z.rootCount+'; marks '+z.marks+'; potential '+z.potential:'Total links '+z.links+'; root ranks '+roots.map(r=>r.children.length).join(', '),'hp-meta');}
for(const[a,b]of edges){const p=pos[a],q=pos[b],dx=q.x-p.x,dy=q.y-p.y,l=Math.hypot(dx,dy);body+='<path data-edge="'+a+':'+b+'" d="M'+(p.x+dx/l*radius)+' '+(p.y+dy/l*radius)+' L'+(q.x-dx/l*radius)+' '+(q.y-dy/l*radius)+'" stroke="#527585" stroke-width="1.7" fill="none" marker-end="url(#hp-arrow)"/>';}
for(const n of nodes){const p=pos[n.id],active=z.focus?.includes(n.id);body+='<g data-entity="node-'+n.id+'" data-node="'+n.id+'"><circle cx="'+p.x+'" cy="'+p.y+'" r="'+radius+'" fill="'+(active?'#d7ede9':'#fff')+'" stroke="'+(n.marked?'#bd793b':'#5d8996')+'" stroke-width="'+(n.marked?3:1.5)+'"/>'+txt(p.x,p.y-3,n.key,'hp-key'+(String(n.key).length>3?' hp-long':String(n.key).length>2?' hp-medium':''),'middle')+txt(p.x,p.y+17,n.label,'hp-id','middle')+'</g>';}
return body+'</svg>';}
function makeModel(id,title,raw){const{spec,states,result}=evaluate(raw);return{id,title,spec,result,kind:'exact-discrete',invariant:'Every discrete checkpoint stores the exact records, active size or forest edges. Interpolation demonstrates movement between checkpoints and is not an extra certified algorithm state.',frames:states.map((z,i)=>({svg:svg(spec,z),caption:'Checkpoint '+(i+1)+' of '+states.length,snapshot:{inputs:spec,state:z,result:i===states.length-1?result:null},teaching:{currentState:title,operation:z.action,why:z.why,reading:z.kind==='array'?'Match array positions with connected tree nodes. Blue cells are active; tan cells are final suffix. IDs follow records through repair.':'Read actual forest edges, root degree and marked nonroots. A transient equal-rank collision or pending second-loss cascade is labeled temporary.',checks:[{mathHtml:'Completed operation checkpoint',result:String(z.complete)},{mathHtml:z.kind==='array'?'Current active heap order':'Forest status',result:z.kind==='array'?String(z.valid):z.complete?'Completed declared forest':'Temporary repair/consolidation'}]}}))};}
if(typeof module!=='undefined')module.exports={validate,evaluate,makeModel};if(typeof document==='undefined')return;
function followPorts(host){const sync=()=>{for(const svg of host.querySelectorAll('svg')){const inv=svg.getCTM()?.inverse();if(!inv)continue;for(const edge of svg.querySelectorAll('[data-edge]')){const[a,b]=edge.dataset.edge.split(':'),ca=svg.querySelector('[data-node="'+a+'"] circle'),cb=svg.querySelector('[data-node="'+b+'"] circle');if(!ca||!cb)continue;const center=c=>new DOMPoint(c.cx.baseVal.value,c.cy.baseVal.value).matrixTransform(c.getCTM()).matrixTransform(inv),p=center(ca),q=center(cb),dx=q.x-p.x,dy=q.y-p.y,l=Math.hypot(dx,dy);if(l<1)continue;edge.setAttribute('d','M'+(p.x+dx/l*ca.r.baseVal.value)+' '+(p.y+dy/l*ca.r.baseVal.value)+' L'+(q.x-dx/l*cb.r.baseVal.value)+' '+(q.y-dy/l*cb.r.baseVal.value));}}};const observer=new MutationObserver(sync);observer.observe(host,{subtree:true,childList:true,attributes:true,attributeFilter:['cx','cy','transform']});sync();return()=>observer.disconnect();}
function mount(host,m){if(!host.querySelector('.hp-controls')){const c=document.createElement('div');c.className='hp-controls';c.innerHTML='<button data-reset>Restart</button><button data-prev>Previous</button><button data-play>Play</button><button data-next>Next</button><label>Speed<select data-speed></select></label><label>Step<input type="range" data-seek min="0" value="0"></label>';host.querySelector('.hp-stage').before(c);}for(const cls of['hp-caption','hp-formula','hp-print'])if(!host.querySelector('.'+cls)){const e=document.createElement('div');e.className=cls;host.append(e);}const p=AdvancedSimulations.mount(host,m,{topic:'a_heap',prefix:'hp',retainDrawing:true}),stop=followPorts(host),dispose=p.dispose;p.dispose=()=>{stop();dispose();};return p;}
async function boot(){const data=await(await fetch('a_heap-models.json')).json();globalThis.HeapPlayers=[];for(const host of document.querySelectorAll('[data-hp-model]')){const m=data.models.find(q=>q.id===host.dataset.hpModel);if(!m)throw Error('Missing heap model');HeapPlayers.push(mount(host,m));}let active;const form=document.querySelector('#hp-form'),out=document.querySelector('#hp-output'),error=document.querySelector('#hp-error');form.addEventListener('submit',e=>{e.preventDefault();try{const parts=form.elements.keys.value.split(',');if(parts.some(x=>!x.trim()))throw Error('Every comma-separated key must be present.');const keys=parts.map(x=>Number(x.trim()));if(keys.length>15)throw Error('The editable compact laboratory accepts at most 15 entries.');const raw={operation:form.elements.operation.value,keys,orientation:form.elements.orientation.value,arity:Number(form.elements.arity.value)};if(raw.operation==='insert'&&keys.length===15)throw Error('Insertion needs at most 14 initial entries.');if(['insert','change'].includes(raw.operation)){if(!form.elements.value.value.trim())throw Error('A new key is required.');raw.value=Number(form.elements.value.value);}if(['delete','change'].includes(raw.operation)){if(!form.elements.index.value.trim())throw Error('A target index is required.');raw.index=Number(form.elements.index.value);}if(['topk','frontier'].includes(raw.operation))raw.k=Number(form.elements.k.value);const model=makeModel('editable-heap','Your exact heap operation',raw);active?.dispose();out.innerHTML='<section class="hp-model"><h3>'+esc(model.title)+'</h3><div class="hp-stage"></div></section><h3>Exact result</h3><pre>'+esc(JSON.stringify(model.result,null,2))+'</pre>';active=mount(out.firstChild,model);globalThis.HeapLab=active;error.textContent='';}catch(e){error.textContent=e.message;}});form.dispatchEvent(new Event('submit',{cancelable:true}));}boot().catch(e=>{document.querySelector('#hp-error').textContent=e.message;throw e;});
})();
